mapper.select:
SELECT *
FROM FACILITIES
WHERE FACILITY_ID = #{facilityId}
  AND MANAGERS_ID = #{managerId}

mapper.update:
UPDATE FACILITIES
SET NAME       = #{facility.name,     jdbcType=VARCHAR},
    DOMAIN     = #{facility.domain,   jdbcType=VARCHAR},
    FLOOR      = #{facility.floor,    jdbcType=VARCHAR},
    ZONE       = #{facility.zone,     jdbcType=VARCHAR},
    ADDRESS    = #{facility.address,  jdbcType=VARCHAR},
    INSPECTOR_ID = #{facility.inspectorId, jdbcType=INTEGER}
WHERE FACILITY_ID = #{facility.facilityId, jdbcType=INTEGER}
  AND MANAGERS_ID = #{managerId, jdbcType=INTEGER}

mapper.delete:
DELETE FROM FACILITIES
WHERE FACILITY_ID = #{facilityId}
  AND MANAGERS_ID = #{managerId}

mapper.select:
SELECT t.*
FROM CHECKLIST_TEMPLATES t
         JOIN FACILITIES f ON f.FACILITY_ID = t.FACILITY_ID
WHERE t.FACILITY_ID = #{facilityId}
  AND f.MANAGERS_ID = #{managerId}

SELECT i.*
FROM INSPECTIONS i
         JOIN FACILITIES f ON f.FACILITY_ID = i.FACILITY_ID
WHERE i.FACILITY_ID = #{facilityId}
  AND f.MANAGERS_ID = #{managerId}
ORDER BY i.INSPECTION_ID DESC

SELECT i.*
FROM INSPECTIONS i
         JOIN FACILITIES f ON f.FACILITY_ID = i.FACILITY_ID
WHERE i.FACILITY_ID = #{facilityId}
  AND f.MANAGERS_ID = #{managerId}
  AND  i.SUBMITTED_AT >=  #{startD}
  AND  i.SUBMITTED_AT <   (#{endD} + INTERVAL '1' DAY)
ORDER BY i.INSPECTION_ID DESC

mapper.update:
UPDATE CHECKLIST_TEMPLATES t
SET t.FACILITY_ID = #{facilityId}
WHERE t.TEMPLATE_ID IN

    #{id}

AND EXISTS (
SELECT 1
FROM FACILITIES f
WHERE f.FACILITY_ID = #{facilityId}
AND f.MANAGERS_ID = #{managerId}
)
